#!/usr/bin/env python3
"""
Closfa — Apply Feed UI Changes
────────────────────────────────
Run this from INSIDE your closfa project folder:

    python3 apply-changes.py

It will:
  1. Write 11 new / updated files (feed UI, queries, relations, etc.)
  2. Run npm install to make sure dependencies are in sync
  3. Clean up any stale generated files

Nothing else is touched.
"""

import os, sys, subprocess, base64, tarfile, io, shutil

# ── Guard ────────────────────────────────────────────────────
if not os.path.exists("package.json"):
    print("\n❌  Run this script from inside your closfa project folder\n")
    sys.exit(1)

try:
    import json
    name = json.load(open("package.json")).get("name", "")
    if name != "closfa":
        print(f"\n❌  package.json name is '{name}', expected 'closfa'\n")
        sys.exit(1)
except Exception:
    pass  # lenient — just check the file exists

print("\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
print("  Closfa  ·  Applying feed UI changes")
print("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n")

# ── Embedded tar.gz (all 11 changed files) ────────────────────
TAR_B64 = """"""

tar_bytes = base64.b64decode(TAR_B64)
tar_file  = tarfile.open(fileobj=io.BytesIO(tar_bytes), mode="r:gz")

extracted = []
for member in tar_file.getmembers():
    # Ensure parent directory exists
    dest = member.name
    parent = os.path.dirname(dest)
    if parent:
        os.makedirs(parent, exist_ok=True)
    # Extract
    src = tar_file.extractfile(member)
    if src is not None:
        with open(dest, "wb") as f:
            f.write(src.read())
        extracted.append(dest)
        print(f"  ✅  {dest}")

tar_file.close()

# ── npm install (sync lockfile) ───────────────────────────────
print("\n📦  Running npm install...")
npm_cmd = "npm.cmd" if sys.platform == "win32" else "npm"
result = subprocess.run([npm_cmd, "install"], capture_output=True, text=True)
if result.returncode != 0:
    print("  ⚠️  npm install had warnings:", result.stderr[-200:])
else:
    print("  ✅  Dependencies up to date")

# ── Remove stale auto-generated route tree (will regenerate on dev) ──
stale = ["src/routeTree.gen.ts"]
for f in stale:
    if os.path.exists(f):
        os.remove(f)
        print(f"  🗑   Removed stale {f} (regenerates on next dev start)")

print()
print("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
print(f"  Done!  {len(extracted)} files written.")
print()
print("  Next steps:")
print("  1. Set your .dev.vars environment variables")
print("  2. Run:  npm run dev")
print("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n")
